vec2 uvb = vec2(1.0 - uv.x,uv.y);
ret = texture(sampler_main, uva).x + texture(sampler_main, uvb).x;
vec3 blurs = GetBlur1(uva).x + GetBlur3(uva).x;
blurs += GetBlur1(uvb).x + GetBlur3(uvb).x;
vec2 uv3 = (uv-.5)*(1.0 - GetBlur1(uv).xy.zzz)+.5;
ret += clamp01(pow(texture(sampler_main, uv3).zzz,.5)*(1.0 - ret.x * 2.0)),
ret += clamp01(pow(GetBlur1(uv3).zzz,.5)*(1.0 - ret.x * 2.0)),
ret = mix(
blurs,
ret,
pow(ret, 1.0 ));
ret = pow(ret,vec3( 5.0 , 1.0 ,.5));
ret += pow(texture(sampler_main, vec2(uv.x,1.0 - uv.y)).yyy+texture(sampler_main, 1.0 - uv).yyy,vec3(.6,.95, 5.0 ));
vec4 noise9 = tex3D(sampler_noisevol_hq,
((uv3.xyy*q28
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3( 1.0 , 1.0 , 0.0 )*0.05 +
uTime*vec3( 0.0 , 0.0 , 1.0 )*q31
);
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5;
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5;
ret-=slow_roam_sin*roam_cos.zxy*.5;
}

